    /** The page each realm's section starts on (0-based), so the book opens where you stand. */
    public static int start(String realm) {
        return switch (realm) {
            case "grove" -> 2;
            case "skyreach" -> 14;
            case "hollow" -> 26;
            case "drowned" -> 38;
            case "pale" -> 50;
            case "scarlet" -> 62;
            case "clockwork" -> 74;
            case "mycelial" -> 89;
            case "last" -> 104;
            default -> 0;
        };
    }
